sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

    var dateValue = g_form.getValue('date');
    var courseValue = g_form.getValue('course');
    var nameValue = g_form.getValue('name');

    if (!dateValue) {
        dateValue = '';
    }
    if (!courseValue) {
        courseValue = '';
    }

    var nameParts = nameValue.split(' - ');
    var currentDate = nameParts[0] || '';
    var currentCourse = nameParts[1] || '';
	if (newValue) {
		currentDate = newValue;
	}

    var newNameValue = currentDate + ' - ' + currentCourse;

    g_form.setValue('name', newNameValue);

}
